mapper.select:
select coalesce(sum(p.payment_amount), 0) from fin_sale_payment p join fin_sale_record r on p.sale_id = r.sale_id where p.payment_date >= curdate() and p.payment_date < date_add(curdate(), interval #{windowDays} day) and p.del_flag = '0' and r.dept_id = #{params.deptId}
and r.dept_id in
#{deptId}

select coalesce(sum(p.payment_amount), 0) from fin_sale_payment p join fin_sale_record r on p.sale_id = r.sale_id where p.del_flag = '0' and p.payment_date >= date_sub(curdate(), interval 7 day) and r.dept_id = #{deptId}
and r.dept_id in
#{deptId}

select snapshot_id, dept_id, forecast_date, window_days, forecast_receivable_amount, actual_receivable_amount, deviation_amount, deviation_rate, pressure_level from finance_cashflow_forecast_snapshot
and dept_id = #{deptId}
and dept_id in
#{deptId}
order by forecast_date desc, window_days asc limit 30
